import os
import requests
from speech_models import TranscriptionConfig

class AzureSpeechClient:
    def __init__(self, config: TranscriptionConfig):
        self.config = config
        self.api_key = config.api_key or os.environ.get('AZURE_SPEECH_KEY')
        if not self.api_key:
            raise ValueError("Azure Speech API key not found. Please set AZURE_SPEECH_KEY environment variable or pass it in config.")
        self.region = config.region
        self.base_url = f"https://{{self.region}}.api.cognitive.microsoft.com/speechtotext/v3.2"

    def _get_headers(self):
        return {
            'Ocp-Apim-Subscription-Key': self.api_key,
            'Content-Type': 'application/json'
        }

    def submit_transcription_job(self, display_name: str, locale: str, content_urls: list, properties: dict = None):
        url = f"{self.base_url}/transcriptions"
        body = {
            'displayName': display_name,
            'locale': locale,
            'contentUrls': content_urls,
            'properties': properties or {}
        }
        response = requests.post(url, headers=self._get_headers(), json=body)
        response.raise_for_status()
        return response.json()

    def get_transcription_job(self, job_id: str):
        url = f"{self.base_url}/transcriptions/{job_id}"
        response = requests.get(url, headers=self._get_headers())
        response.raise_for_status()
        return response.json()

    def get_transcription_result(self, result_uri: str):
        response = requests.get(result_uri, headers=self._get_headers())
        response.raise_for_status()
        return response.json()

import time
import os
from speech_client import AzureSpeechClient
from speech_models import TranscriptionConfig, TranscriptionJob, TranscriptionResult

def poll_transcription(job: TranscriptionJob, config: TranscriptionConfig = None, poll_interval_seconds: int = 5):
    config = config or TranscriptionConfig()
    client = AzureSpeechClient(config)

    job_id = job.job_id.split('/')[-1] # Extract actual job ID from the self URI

    while True:
        job_status_response = client.get_transcription_job(job_id)
        status = job_status_response['status']
        if status == 'Succeeded':
            files_uri = job_status_response['links']['files']
            files_response = requests.get(files_uri, headers=client._get_headers())
            files_response.raise_for_status()
            files_data = files_response.json()

            for file_item in files_data['values']:
                if file_item['kind'] == 'Transcription' and file_item['properties']['contentType'] == 'application/json':
                    transcript_result = client.get_transcription_result(file_item['links']['contentUrl'])
                    return TranscriptionResult.parse_obj(transcript_result)
            raise Exception("Transcription result not found in job files.")
        elif status == 'Failed':
            raise Exception(f"Transcription job failed: {job_status_response.get('properties', {}).get('error', 'Unknown error')}")
        else:
            print(f"Transcription job status: {status}. Polling again in {poll_interval_seconds} seconds...")
            time.sleep(poll_interval_seconds)

import os
from google.cloud import translate_v3 as translate
from speech_models import TranslationPayload

def translate_transcript(payload: TranslationPayload):
    client = translate.TranslationServiceClient()

    project_id = os.environ.get("GOOGLE_CLOUD_PROJECT_ID")
    if not project_id:
        raise ValueError("Google Cloud Project ID not found. Please set GOOGLE_CLOUD_PROJECT_ID environment variable.")

    location = "global"
    parent = f"projects/{project_id}/locations/{location}"

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [payload.text],
            "target_language_code": payload.target_language_code,
            "source_language_code": payload.source_language_code,
        }
    )

    translated_text = []
    for translation in response.translations:
        translated_text.append(translation.translated_text)

    return {"translated_text": " ".join(translated_text)}

import os
from googleapiclient import discovery
from speech_models import ModerationPayload

def moderate_transcript(payload: ModerationPayload):
    client = discovery.build(
        "commentanalyzer",
        "v1alpha1",
        developerKey=os.environ.get("PERSPECTIVE_API_KEY"),
        static_discovery=False
    )

    if not os.environ.get("PERSPECTIVE_API_KEY"):
        raise ValueError("Perspective API key not found. Please set PERSPECTIVE_API_KEY environment variable.")

    analyze_request = {
        'comment': { 'text': payload.text },
        'requestedAttributes': { 'TOXICITY': {} }
    }

    response = client.comments().analyze(body=analyze_request).execute()

    toxicity_score = response['attributeScores']['TOXICITY']['summaryScore']['value']

    return {"toxicity_score": toxicity_score}

import os
import google.generativeai as genai
from speech_models import EmbeddingPayload

def transcript_embedding(payload: EmbeddingPayload):
    genai.configure(api_key=os.environ.get("GEMINI_API_KEY"))
    if not os.environ.get("GEMINI_API_KEY"):
        raise ValueError("Gemini API key not found. Please set GEMINI_API_KEY environment variable.")

    model = genai.GenerativeModel('text-embedding-004') # Using a specific embedding model

    embeddings = []
    for segment in payload.text_segments:
        response = model.embed_content(content=segment)
        embeddings.append(response['embedding'])

    return {"embeddings": embeddings}
